(37961, 'Malachi 3:18', 'Malachi', 3, 18, 'او بيا به تاسو د صادقانو او بدعملو په اَنجام کښې فرق وګورئ، او هم به تاسو د هغوئ اَنجام کښې فرق وګورئ څوک چې د خُدائ پاک خِدمت کوى او څوک يې چې نۀ کوى.“', 'او بیا به تاسو د صادقانو او بدعملو په انجام کشې فرق وګوری، او هم به تاسو د هغوی انجام کشې فرق وګوری چوک چې د خدای پاک خدمت کوی او چوک یې چې نۀ کوی.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Malachi_3_18.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(37962, 'Psalms 94:1', 'Psalms', 94, 1, 'ای څښتنه، ته یې خدای غچ اخیستونکی ای غچ اخیستونکیه خدایه، وښایه ته خپل جلال!', 'ای چشتنه، ته یې خدای غچ اخیستونکی ای غچ اخیستونکیه خدایه، وشایه ته خپل جلال!', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_94_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37963, 'Psalms 94:2', 'Psalms', 94, 2, 'ای د نړۍ قاضي راپاڅېږه ته ورسوه د خپلو بدو عملونو په سزا مغروران!', 'ای د نری قاضی راپاچېزه ته ورسوه د خپلو بدو عملونو په سزا مغروران!', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_94_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37964, 'Psalms 94:3', 'Psalms', 94, 3, 'ترڅو به بدکاران ای څښتنه بدکاران به خوشحالي کوي تر کومه؟', 'ترچو به بدکاران ای چشتنه بدکاران به خوشحالی کوی تر کومه؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_94_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37965, 'Psalms 94:4', 'Psalms', 94, 4, 'هغوی د کبر او غرور غټې خبرې کوي ټول بد‌کرداره خلک لافې وهي', 'هغوی د کبر او غرور غتې خبرې کوی تول بد‌کرداره خلک لافې وهی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_94_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37966, 'Psalms 94:5', 'Psalms', 94, 5, 'ستا خلک تر‌پښو لاندې کوي څښتنه هغوی کړي ظلم ستا په خپلو خلکو باندې', 'ستا خلک تر‌پشو لاندې کوی چشتنه هغوی کری ظلم ستا په خپلو خلکو باندې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_94_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37967, 'Psalms 94:6', 'Psalms', 94, 6, 'بل ځایي خلک او کونډې وژني هم یتیمان قتلوي', 'بل جایی خلک او کوندې وژنی هم یتیمان قتلوی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_94_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37968, 'Psalms 94:7', 'Psalms', 94, 7, 'وایي هغوی چې څښتن نه ویني مونږ نه یې پام کیږي مونږ ته د یعقوب د خدای', 'وایی هغوی چې چشتن نه وینی مونز نه یې پام کیزی مونز ته د یعقوب د خدای', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_94_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37969, 'Psalms 94:8', 'Psalms', 94, 8, 'ای د قوم بې‌عقلو خلکو پوه شئ! کله به تاسو هوښیارېږئ ساده‌ګانو خلکو؟', 'ای د قوم بې‌عقلو خلکو پوه شی! کله به تاسو هوشیارېزی ساده‌ګانو خلکو؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_94_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37970, 'Psalms 94:9', 'Psalms', 94, 9, 'هغه چې مونږ ته یې راکړی دی غوږ ایا هغه په خپله نه اوري څه؟ هغه چې سترګې پیدا کړې دي ایا هغه په خپله نه ویني څه؟', 'هغه چې مونز ته یې راکری دی غوز ایا هغه په خپله نه اوری چه؟ هغه چې سترګې پیدا کرې دی ایا هغه په خپله نه وینی چه؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_94_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37971, 'Psalms 94:10', 'Psalms', 94, 10, 'څوک چې په خپله سموي قومونه نو دوی ته نه شي ورکولای سزا؟ هغه چې خپله دی استاذ د ټولو نو ایا نه لري په خپله پوهه؟', 'چوک چې په خپله سموی قومونه نو دوی ته نه شی ورکولای سزا؟ هغه چې خپله دی استاذ د تولو نو ایا نه لری په خپله پوهه؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_94_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37972, 'Psalms 94:11', 'Psalms', 94, 11, 'څښتن پوهیږي د انسان په خیالو هغه پوهیږي چې خیالونه یې باطل او پوچ دي', 'چشتن پوهیزی د انسان په خیالو هغه پوهیزی چې خیالونه یې باطل او پوچ دی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_94_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37973, 'Psalms 94:12', 'Psalms', 94, 12, 'بختور دی هغه څوک چې ته یې سموې، څښتنه ورته تعلیم د خپل شریعت ورکوې', 'بختور دی هغه چوک چې ته یې سموې، چشتنه ورته تعلیم د خپل شریعت ورکوې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_94_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
